package pro.livemic.studio;
import android.view.*;
import java.io.File;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import org.robolectric.shadows.ShadowLooper;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=35,instrumentedPackages={"pro.livemic.studio"},shadows={StudioScreenshotTest.Audio.class,StudioScreenshotTest.Composer.class,StudioScreenshotTest.Harmony.class}) @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class LiveConsoleScreenshotTest {
 @Test public void liveConsoleInBothLanguagesAndLargeText()throws Exception {
  File out=new File(System.getProperty("user.dir"),"build/studio-screenshots");out.mkdirs();java.lang.reflect.Field field=AudioService.class.getDeclaredField("countdown");field.setAccessible(true);RecordingCountdown countdown=(RecordingCountdown)field.get(null);
  for(boolean english:new boolean[]{false,true})for(float scale:new float[]{1f,1.3f})for(int width:new int[]{412,360}){
   int height=width==412?893:800;RuntimeEnvironment.setQualifiers("w"+width+"dp-h"+height+"dp-mdpi");RuntimeEnvironment.setFontScale(scale);AppLanguage.set(RuntimeEnvironment.getApplication(),english);AudioService.active=false;RecordingManager.active=false;countdown.cancel();
   MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();a.handler.removeCallbacks(a.tick);a.composer.worker.submit(()->{}).get();ShadowLooper.idleMainLooper();a.handler.removeCallbacks(a.tick);a.root.dispatchApplyWindowInsets(new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.of(0,36,0,24)).build());a.chooseTab(0);String prefix="v36-"+(english?"en":"ko")+"-"+width+(scale==1?"-default":"-large");
   float[] stats=new float[22];StudioScreenshotTest.Audio.supplied=stats;a.tick.run();a.handler.removeCallbacks(a.tick);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-idle.png"),false);android.graphics.Rect rec=StudioScreenshotTest.bounds(a,a.recButton);assertEquals(3,a.nav.getChildCount());assertTrue(StudioScreenshotTest.bounds(a,a.nav).bottom<=StudioScreenshotTest.bounds(a,a.pageScroll).top);assertTrue(rec.top>=a.pageScroll.getBottom());assertTrue(rec.bottom<=a.root.getHeight()-a.root.getPaddingBottom());
   assertTrue("page fits viewport",a.page.getHeight()<=a.pageScroll.getHeight());a.pageScroll.scrollTo(0,a.page.getHeight());assertEquals(0,a.pageScroll.getScrollY());assertEquals(rec,StudioScreenshotTest.bounds(a,a.recButton));
   for(android.widget.Button b:a.liveScreen.selectors){android.graphics.Rect bounds=StudioScreenshotTest.bounds(a,b);assertTrue("selector width "+bounds,bounds.width()>=48);assertTrue("selector height "+bounds,bounds.height()>=48);assertTrue(bounds.bottom<=a.pageScroll.getBottom());assertTrue(b.getLayout()!=null && b.getLayout().getEllipsisCount(b.getLayout().getLineCount()-1)==0);}
   float[] original=a.values.clone();for(int i=0;i<6;i++)a.values[a.liveScreen.ids[i]]=a.liveScreen.maxs[i];a.liveScreen.sync();StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-idle.png"),false);
   for(android.widget.Button b:a.liveScreen.selectors){android.text.Layout layout=b.getLayout();assertNotNull(layout);int last=layout.getLineCount()-1;assertEquals("selector value must be visible: "+b.getText(),b.length(),layout.getLineEnd(last));assertEquals(0,layout.getEllipsisCount(last));assertTrue("selector text fits height: "+b.getText(),layout.getHeight()<=b.getHeight()-b.getCompoundPaddingTop()-b.getCompoundPaddingBottom());}
   for(int i=0;i<6;i++)a.values[a.liveScreen.ids[i]]=original[a.liveScreen.ids[i]];a.liveScreen.sync();StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-idle.png"),false);
   assertNotNull(a.liveScreen.dial.createAccessibilityNodeInfo().getRangeInfo());a.liveScreen.select(4);android.os.Bundle value=new android.os.Bundle();value.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,700);a.liveScreen.dial.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),value);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-delay.png"),false);a.liveScreen.select(2);value.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,2);a.liveScreen.dial.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),value);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-voice.png"),false);
   a.pageScroll.scrollTo(0,0);AudioService.active=true;RecordingManager.active=true;stats[0]=440;stats[2]=69;stats[3]=.08f;stats[8]=12;stats[10]=1;stats[16]=1;a.tick.run();a.handler.removeCallbacks(a.tick);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-recording.png"),false);assertTrue(a.liveScreen.clock.getText().toString().contains("00:12"));
   RecordingManager.paused=true;a.tick.run();a.handler.removeCallbacks(a.tick);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-paused.png"),false);assertTrue(a.liveScreen.clock.getText().toString().contains("00:12"));RecordingManager.paused=false;
   RecordingManager.active=false;stats[17]=1;a.tick.run();a.handler.removeCallbacks(a.tick);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-safety.png"),false);assertTrue(a.liveScreen.route.getText().toString().contains(english?"safety":"보호"));
   if(english&&width==412&&scale==1f){a.liveScreen.inputButton.performClick();android.app.Dialog input=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(input);StudioScreenshotTest.captureSheet(a,input.getWindow().getDecorView().findViewById(android.R.id.content),new File(out,prefix+"-input-sheet.png"));input.dismiss();a.outputButton.performClick();android.app.Dialog output=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(output);StudioScreenshotTest.captureSheet(a,output.getWindow().getDecorView().findViewById(android.R.id.content),new File(out,prefix+"-output-sheet.png"));output.dismiss();a.chooseTab(6);StudioScreenshotTest.capture(a,width,height,new File(out,prefix+"-detailed-effects.png"),false);a.chooseTab(0);}
   stats[17]=0;countdown.arm(5,android.os.SystemClock.elapsedRealtime());a.tick.run();a.handler.removeCallbacks(a.tick);assertTrue(a.liveScreen.clock.getText().toString().contains(english?"IN":"예약"));countdown.cancel();a.io.shutdown();StudioScreenshotTest.Audio.supplied=null;AudioService.active=false;
  }AppLanguage.set(RuntimeEnvironment.getApplication(),false);RuntimeEnvironment.setFontScale(1f);
 }
}
